<!-- The (i) next to one row or value of the AI-table explanation: its lines in a tooltip above it, all of them as the aria-label. -->
<template>
  <span
    v-if="text"
    role="img"
    tabindex="0"
    data-test="ai-explanation-info"
    :aria-label="text"
    class="inline-flex shrink-0 cursor-help rounded-sm text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
    ><Icon icon="mdi:information-outline" class="size-4" /><q-tooltip
      max-width="340px"
      anchor="top middle"
      self="bottom middle"
      :offset="[0, 6]"
      class="text-xs leading-relaxed"
      ><div
        v-for="(line, index) in shown"
        :key="index"
        :class="{ 'mt-1': index > 0 }"
      >
        {{ line }}
      </div></q-tooltip
    ></span
  >
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';

export default defineComponent({
  name: 'ExplanationInfo',
  components: { Icon },
  props: {
    lines: {
      type: Array as PropType<(string | null | undefined)[]>,
      required: true,
    },
  },
  computed: {
    shown(): string[] {
      return this.lines.filter((line): line is string =>
        Boolean(line && line.trim()),
      );
    },
    text(): string {
      return this.shown.join(' ');
    },
  },
});
</script>
