<template>
  <div
    class="ai-explanation-content flex flex-col gap-6 text-sm text-foreground"
    data-test="ai-explanation-content"
  >
    <!-- 1. the four steps, as counts -->
    <ol
      v-if="explanation.steps"
      class="m-0 grid list-none grid-cols-1 gap-3 p-0 sm:grid-cols-2 xl:grid-cols-4"
      data-test="ai-explanation-steps"
    >
      <li
        v-for="step in stepCards"
        :key="step.key"
        class="flex min-w-0 flex-col gap-1 rounded-lg border bg-card p-3"
        :class="step.key === 'result' ? 'border-primary/50' : 'border-border'"
        :data-test="`ai-explanation-step-${step.key}`"
      >
        <div class="ai-line mb-1">
          <span
            class="flex size-6 shrink-0 items-center justify-center rounded-full border text-xs font-semibold"
            :class="
              step.key === 'result'
                ? 'border-primary bg-primary text-primary-foreground'
                : 'border-border bg-muted text-foreground'
            "
            >{{ step.number }}</span
          >
          <span class="min-w-0 flex-1 truncate font-semibold">{{
            $t(step.titleKey)
          }}</span>
          <ExplanationInfo :lines="stepInfo(step)" />
        </div>

        <template v-if="step.key === 'document'">
          <span
            class="truncate"
            :title="explanation.steps.document.filename || ''"
            >{{ explanation.steps.document.filename || '—' }}</span
          >
          <span class="text-muted-foreground"
            >{{
              $t('ai_explain_pages_count', {
                count: explanation.steps.document.pages ?? '—',
              })
            }}
            · {{ explanation.steps.document.doc_type }}</span
          >
        </template>

        <template v-else-if="step.key === 'extraction'">
          <span
            ><b class="tabular-nums">{{
              explanation.steps.extraction.raw_columns
            }}</b>
            {{ $t('ai_explain_raw_columns_short') }} ·
            <b class="tabular-nums">{{ explanation.steps.extraction.rows }}</b>
            {{ $t('ai_explain_rows') }}</span
          >
          <span class="text-muted-foreground" data-test="ai-explanation-tier"
            >{{ $t('ai_explain_tier') }}: {{ tierText(explanation) }}</span
          >
          <span v-if="structuredOutput" class="ai-pill-row mt-1">
            <span
              :class="[
                `ai-explanation-pill--${structuredOutput.tone}`,
                pillClass(structuredOutput.tone),
              ]"
              :aria-label="soExplainer"
              class="ai-pill rounded-full border text-xs font-medium"
              data-test="ai-explanation-so-pill"
              >{{ soBadge }}</span
            >
            <ExplanationInfo :lines="soInfo" />
          </span>
        </template>

        <template v-else-if="step.key === 'mapping'">
          <span
            ><b class="tabular-nums">{{ explanation.steps.mapping.mapped }}</b>
            {{ $t('ai_explain_mapped') }}</span
          >
          <span class="text-muted-foreground"
            >{{ explanation.steps.mapping.identity }}
            {{ $t('ai_explain_same_name') }}</span
          >
          <span
            class="text-xs text-muted-foreground"
            data-test="ai-explanation-mapping-stats"
            >{{ mappingStats }}</span
          >
        </template>

        <template v-else>
          <span data-test="ai-explanation-result-line"
            ><b class="tabular-nums">{{ counts.filled }}</b>
            {{ $t('ai_explain_legend_filled') }} ·
            <b class="tabular-nums">{{ counts.missing }}</b>
            {{ $t('ai_explain_not_found') }}</span
          >
          <span class="text-muted-foreground"
            >{{ explanation.steps.result.rows }}
            {{ $t('ai_explain_rows') }}</span
          >
        </template>
      </li>
    </ol>

    <!-- 2. the table as the reader knows it: configured columns across, what each got below -->
    <section
      class="ai-explanation-mapping flex flex-col gap-3"
      data-test="ai-explanation-mapping"
    >
      <div class="flex flex-wrap items-center justify-between gap-3">
        <div class="flex min-w-0 flex-wrap items-center gap-x-4 gap-y-1">
          <h3 class="m-0 flex items-center gap-1.5 text-lg font-semibold">
            {{ $t('ai_explain_mapping_short') }}
            <span
              class="text-sm font-normal text-muted-foreground"
              data-test="ai-explanation-column-count"
              >{{
                $t('ai_explain_columns_count', {
                  total: explanation.configuration.column_count,
                  ai: counts.filled + counts.missing,
                })
              }}</span
            >
            <ExplanationInfo
              :lines="[
                $t('ai_explain_mapping_info'),
                $t('ai_explain_mapping_legend'),
              ]"
            />
          </h3>
          <ul
            class="m-0 flex list-none flex-wrap gap-x-3 gap-y-1 p-0 text-xs text-muted-foreground"
            data-test="ai-explanation-legend"
          >
            <li
              v-for="item in legend"
              :key="item.state"
              class="flex items-center gap-1.5"
            >
              <span class="size-2 rounded-full" :class="item.dot" />{{
                $t(item.key)
              }}
            </li>
          </ul>
        </div>
        <q-input
          v-model="query"
          dense
          outlined
          clearable
          :placeholder="$t('ai_explain_search_columns')"
          :aria-label="$t('ai_explain_search_columns')"
          class="w-full sm:w-64"
          data-test="ai-explanation-search"
        >
          <template #prepend>
            <Icon icon="mdi:magnify" class="size-4 text-muted-foreground" />
          </template>
        </q-input>
      </div>

      <p
        v-if="needle && !visibleColumns.length"
        class="m-0 rounded-md border border-border bg-muted px-3 py-2 text-muted-foreground"
        data-test="ai-explanation-search-empty"
      >
        {{ $t('ai_explain_search_empty', { query: query }) }}
      </p>

      <div
        v-else
        class="ai-explanation-grid-scroll rounded-lg border border-border"
        data-test="ai-explanation-grid"
      >
        <table class="ai-explanation-grid border-collapse text-sm">
          <thead>
            <tr>
              <th
                scope="col"
                class="ai-explanation-grid__corner border-b border-r border-border bg-muted px-3 py-2 text-left text-xs font-medium text-muted-foreground"
              >
                {{ $t('ai_explain_column') }}
              </th>
              <th
                v-for="column in visibleColumns"
                :key="'cfg-' + column.key"
                scope="col"
                :class="[
                  `ai-explanation-chip--${columnState(column)}`,
                  headClass(column),
                ]"
                class="border-b border-r border-border px-3 py-2 text-left font-medium"
                :data-test="`ai-explanation-cfg-${column.key}`"
              >
                <div class="ai-line">
                  <span
                    class="size-2 shrink-0 rounded-full"
                    :class="dotClass(column)"
                  />
                  <span class="truncate" :title="column.label">{{
                    column.label
                  }}</span>
                  <ExplanationInfo :lines="configuredInfo(column)" />
                </div>
                <div
                  class="mt-0.5 text-xs font-normal text-muted-foreground"
                  data-test="ai-explanation-state"
                >
                  {{ stateText(column) }}
                </div>
              </th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="row in gridRows" :key="row.key">
              <th
                scope="row"
                class="ai-explanation-grid__corner border-b border-r border-border bg-muted px-3 py-2 text-left text-xs font-medium text-muted-foreground"
              >
                <span class="ai-line"
                  >{{ $t(row.labelKey) }}
                  <ExplanationInfo :lines="[$t(row.infoKey)]"
                /></span>
              </th>
              <td
                v-for="column in visibleColumns"
                :key="row.key + '-' + column.key"
                class="border-b border-r border-border px-3 py-2"
                :class="{
                  'text-muted-foreground': columnState(column) !== 'filled',
                }"
                :data-test="`ai-explanation-${row.key}-${column.key}`"
              >
                <template v-if="row.key === 'raw'">
                  <span v-if="column.basis && column.raw_key" class="ai-line">
                    <span class="truncate font-medium text-foreground">{{
                      prettyRaw(column)
                    }}</span>
                    <ExplanationInfo :lines="rawInfo(column)" />
                  </span>
                  <span v-else>—</span>
                </template>
                <span
                  v-else-if="row.key === 'example'"
                  class="block truncate"
                  :title="column.example || ''"
                  >{{ column.example || '—' }}</span
                >
                <span
                  v-else-if="row.key === 'rows'"
                  class="tabular-nums"
                  :class="{
                    'font-semibold text-destructive':
                      column.requested_from_ai && column.state === 'empty',
                    'font-semibold text-warning': column.state === 'partial',
                  }"
                  >{{ column.filled_rows }}/{{ column.row_count }}</span
                >
                <span v-else-if="row.key === 'origin'" class="block truncate">{{
                  originLabel(column)
                }}</span>
                <span
                  v-else
                  class="block truncate"
                  :title="column.hint || ''"
                  >{{ column.hint || '—' }}</span
                >
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </section>

    <!-- 3. recommendations: what the reader can act on -->
    <section
      v-if="explanation.recommendations.length"
      class="flex flex-col gap-2"
      data-test="ai-explanation-recommendations"
    >
      <h3 class="m-0 text-lg font-semibold">
        {{ $t('ai_explain_recommendations') }}
      </h3>
      <ul class="m-0 flex list-none flex-col gap-2 p-0">
        <li
          v-for="rec in explanation.recommendations"
          :key="rec.code"
          class="flex items-center gap-2 rounded-md border border-border bg-card px-3 py-2"
          :data-test="`ai-explanation-rec-${rec.code}`"
        >
          <Icon
            :icon="severityIcon(rec.severity)"
            :color="severityColor(rec.severity)"
            class="size-4 shrink-0"
          />
          <b class="min-w-0 truncate font-semibold">{{ text(rec.title) }}</b>
          <ExplanationInfo :lines="[text(rec.text)]" />
          <router-link
            v-if="rec.route && rec.route.startsWith('/')"
            :to="rec.route"
            class="ml-auto shrink-0 text-primary hover:underline"
            >{{ $t('ai_explain_open_setting') }}</router-link
          >
        </li>
      </ul>
    </section>

    <!-- 4. the run that produced the table -->
    <section class="flex flex-col gap-2" data-test="ai-explanation-run">
      <h3 class="m-0 text-lg font-semibold">{{ $t('ai_explain_run') }}</h3>
      <dl
        v-if="explanation.run"
        class="m-0 grid grid-cols-1 gap-x-6 gap-y-2 rounded-lg border border-border bg-card p-4 sm:grid-cols-[max-content_minmax(0,1fr)]"
      >
        <dt class="flex items-center gap-1.5 text-muted-foreground">
          {{ $t('ai_explain_model') }}
          <ExplanationInfo :lines="[$t('ai_explain_info_model')]" />
        </dt>
        <dd class="m-0" data-test="ai-explanation-model">
          {{ tierText(explanation) }}
        </dd>
        <dt class="flex items-center gap-1.5 text-muted-foreground">
          {{ $t('ai_explain_mode') }}
          <ExplanationInfo :lines="[$t('ai_explain_info_mode')]" />
        </dt>
        <dd class="m-0">{{ text(explanation.run.mode_label) }}</dd>
        <dt class="flex items-center gap-1.5 text-muted-foreground">
          {{ $t('ai_explain_check') }}
          <ExplanationInfo :lines="[$t('ai_explain_info_check')]" />
        </dt>
        <dd class="m-0" data-test="ai-explanation-check">
          {{ checkText(explanation.run.structure_valid) }} ·
          {{ text(explanation.run.category_label) }}
        </dd>
        <dt class="flex items-center gap-1.5 text-muted-foreground">
          {{ $t('ai_explain_structured_output') }}
          <ExplanationInfo v-if="structuredOutput" :lines="soInfo" />
        </dt>
        <dd class="m-0" data-test="ai-explanation-structured-output">
          <template v-if="structuredOutput">
            <span
              :class="pillClass(structuredOutput.tone)"
              class="ai-pill rounded-full border text-xs font-medium"
              >{{ soBadge }}</span
            >
          </template>
          <template v-else>
            {{ explanation.configuration.structured_output.status }}
            ({{ explanation.configuration.structured_output.source }})
          </template>
        </dd>
        <dt class="flex items-center gap-1.5 text-muted-foreground">
          {{ $t('ai_explain_calls') }}
          <span data-test="ai-explanation-calls-note"
            ><ExplanationInfo :lines="[$t('ai_explain_calls_note')]"
          /></span>
        </dt>
        <dd class="m-0">
          <ul class="m-0 flex list-none flex-col gap-1 p-0">
            <li
              v-for="call in explanation.run.calls"
              :key="call.run_id || call.started_at || ''"
              class="tabular-nums"
            >
              {{ when(call.started_at) }} · {{ callTier(call) }} ·
              {{
                $t('ai_explain_call_pages', {
                  pages: (call.pages || []).join(', ') || '—',
                })
              }}
              · {{ checkText(call.structure_valid) }}
            </li>
          </ul>
        </dd>
      </dl>
      <p
        v-else
        class="m-0 flex items-center gap-1.5 rounded-md border border-border bg-muted px-3 py-2 text-muted-foreground"
        data-test="ai-explanation-no-run"
      >
        {{ $t('ai_explain_no_run_short') }}
        <ExplanationInfo :lines="[$t('ai_explain_no_run')]" />
      </p>
    </section>

    <!-- 5. the three notes the DEFA flows carry, one (i) each -->
    <ul
      class="m-0 flex list-none flex-wrap gap-x-6 gap-y-2 p-0 text-muted-foreground"
      data-test="ai-explanation-notes"
    >
      <li
        v-for="note in notes"
        :key="note.key"
        class="flex items-center gap-1.5"
        :data-test="`ai-explanation-note-${note.key}`"
      >
        <span class="font-medium">{{ $t(note.labelKey) }}</span>
        <ExplanationInfo :lines="[note.text]" />
      </li>
    </ul>
  </div>
</template>

<script lang="ts">
/**
 * The explanation itself (DOCB-14569) — shared by the dialog and the full
 * page: the four steps, the configured columns laid out like the table with
 * what each got, what to do, the run, and the three notes. Long texts sit
 * behind an (i). The KI-Advisor and the
 * pipeline have their own buttons and dialogs (CORE-6131). Every sentence about the run arrives
 * from the API in DE and EN; the (i) per row and value (CORE-6131) only
 * explains what the row means, from Tolgee keys.
 */
import { computed, defineComponent, inject, type PropType } from 'vue';
import { useTolgee } from '@tolgee/vue';
import { Icon } from '@iconify/vue';
import ExplanationInfo from 'src/components/document/ExplanationInfo.vue';
import type { PipelineText } from 'src/services/analytics/PipelineExplanationService';
import type {
  TableExplanation,
  TableExplanationCall,
  TableExplanationColumn,
  TableExplanationStructuredOutput,
} from 'src/services/analytics/TableExplanationService';

import {
  STATE_DOT,
  columnInfoLines,
  columnState,
  originShort,
  prettyRaw,
  rawInfoLines,
  type ColumnState,
} from 'src/utils/table-explanation-view';

export default defineComponent({
  name: 'AITableExplanationContent',
  components: { ExplanationInfo, Icon },
  props: {
    explanation: {
      type: Object as PropType<TableExplanation>,
      required: true,
    },
  },
  setup() {
    const tolgee = inject('tolgeeContext', null)
      ? useTolgee(['language'])
      : null;
    const uiLanguage = computed(() => tolgee?.value?.getLanguage() || '');
    return { uiLanguage };
  },
  data() {
    return { query: '' as string | null };
  },
  computed: {
    locale(): string {
      const raw = String(this.uiLanguage || this.$i18n?.locale || 'en');
      return raw.split('-')[0] || 'en';
    },
    stepCards(): {
      key: string;
      number: number;
      titleKey: string;
      infoKey: string;
    }[] {
      return [
        {
          key: 'document',
          number: 1,
          titleKey: 'ai_explain_step_document',
          infoKey: 'ai_explain_step_document_info',
        },
        {
          key: 'extraction',
          number: 2,
          titleKey: 'ai_explain_step_extraction',
          infoKey: 'ai_explain_step_extraction_info',
        },
        {
          key: 'mapping',
          number: 3,
          titleKey: 'ai_explain_step_mapping',
          infoKey: 'ai_explain_step_mapping_info',
        },
        {
          key: 'result',
          number: 4,
          titleKey: 'ai_explain_step_result',
          infoKey: 'ai_explain_step_result_info',
        },
      ];
    },
    legend(): { state: ColumnState; key: string; dot: string }[] {
      return [
        {
          state: 'filled',
          key: 'ai_explain_legend_filled',
          dot: STATE_DOT.filled,
        },
        {
          state: 'missing',
          key: 'ai_explain_not_found',
          dot: STATE_DOT.missing,
        },
        { state: 'off', key: 'ai_explain_ai_off', dot: STATE_DOT.off },
        { state: 'hidden', key: 'ai_explain_hidden', dot: STATE_DOT.hidden },
      ];
    },
    /** Structured output at a glance — from the run's evidence, not the preference. */
    structuredOutput(): TableExplanationStructuredOutput | null {
      return this.explanation?.steps?.extraction?.structured_output || null;
    },
    /** Filled and not-found columns first, then those without AI, hidden last; table order within each. */
    tableColumns(): TableExplanationColumn[] {
      const columns = this.explanation?.columns || [];
      const order: ColumnState[] = ['filled', 'missing', 'off', 'hidden'];
      return order.flatMap((state) =>
        columns.filter((c) => this.columnState(c) === state),
      );
    },
    /** One set of counts for the cards and the table, so the numbers add up. */
    counts(): { filled: number; missing: number } {
      const states = this.tableColumns.map((c) => this.columnState(c));
      return {
        filled: states.filter((state) => state === 'filled').length,
        missing: states.filter((state) => state === 'missing').length,
      };
    },
    schemaUsed(): boolean {
      return this.structuredOutput?.used === true;
    },
    soBadge(): string {
      const tone = this.structuredOutput?.tone || 'unknown';
      const known = ['ok', 'warn', 'unverified', 'off'];
      return this.$t(
        `ai_explain_so_badge_${known.includes(tone) ? tone : 'unknown'}`,
      );
    },
    soExplainer(): string {
      const used = this.structuredOutput?.used;
      if (used === true)
        return this.$t('ai_explain_so_explainer_on', {
          count: this.counts.filled + this.counts.missing,
        });
      if (used === false) return this.$t('ai_explain_so_explainer_off');
      return this.$t('ai_explain_so_explainer_unknown');
    },
    /** What structured output is, then what it meant for this run. */
    soInfo(): string[] {
      return [this.$t('ai_explain_so_what'), this.soExplainer];
    },
    mappingStats(): string {
      const mapping = this.explanation?.steps?.mapping;
      if (!mapping) return '';
      return `${mapping.discarded} ${this.$t('ai_explain_discarded')} · ${mapping.collisions} ${this.$t('ai_explain_collisions')} · ${mapping.unknown_raw} ${this.$t('ai_explain_unknown_raw')}`;
    },
    needle(): string {
      return String(this.query || '')
        .trim()
        .toLowerCase();
    },
    visibleColumns(): TableExplanationColumn[] {
      return this.tableColumns.filter((c) => this.matches(c));
    },
    /** What each column got, one row per fact; the hint row only when a column has one. */
    gridRows(): { key: string; labelKey: string; infoKey: string }[] {
      const rows = [
        {
          key: 'raw',
          labelKey: 'ai_explain_row_raw',
          infoKey: 'ai_explain_row_raw_info',
        },
        {
          key: 'example',
          labelKey: 'ai_explain_row_example',
          infoKey: 'ai_explain_row_example_info',
        },
        {
          key: 'rows',
          labelKey: 'ai_explain_row_rows',
          infoKey: 'ai_explain_row_rows_info',
        },
        {
          key: 'origin',
          labelKey: 'ai_explain_origin',
          infoKey: 'ai_explain_row_origin_info',
        },
      ];
      if (this.tableColumns.some((c) => c.hint)) {
        rows.push({
          key: 'hint',
          labelKey: 'ai_explain_hint',
          infoKey: 'ai_explain_row_hint_info',
        });
      }
      return rows;
    },
    notes(): { key: string; labelKey: string; text: string }[] {
      const notes = this.explanation?.notes;
      if (!notes) return [];
      return [
        {
          key: 'stops_at',
          labelKey: 'ai_explain_where_it_stops',
          text: this.text(notes.stops_at),
        },
        {
          key: 'not_shown',
          labelKey: 'ai_explain_not_shown',
          text: this.text(notes.not_shown),
        },
        {
          key: 'next_step',
          labelKey: 'ai_explain_next_step',
          text: this.text(notes.next_step),
        },
      ].filter((note) => note.text);
    },
  },
  methods: {
    tr(key: string, params?: Record<string, unknown>): string {
      return params ? this.$t(key, params) : this.$t(key);
    },
    columnState(column: TableExplanationColumn): ColumnState {
      return columnState(column);
    },
    stateText(column: TableExplanationColumn): string {
      if (this.columnState(column) === 'filled')
        return `${column.filled_rows}/${column.row_count} ${this.$t('ai_explain_rows')}`;
      return originShort(column, this.tr);
    },
    /** Search by column name, technical key, raw name or example value. */
    matches(column: TableExplanationColumn): boolean {
      if (!this.needle) return true;
      return [
        column.label,
        column.key,
        column.raw_key,
        column.raw_name,
        column.example,
        this.prettyRaw(column),
      ].some((value) =>
        String(value || '')
          .toLowerCase()
          .includes(this.needle),
      );
    },
    rawInfo(column: TableExplanationColumn): string[] {
      return [
        ...rawInfoLines(column, this.tr, (value) => this.text(value)),
        this.schemaNote(column),
      ];
    },
    configuredInfo(column: TableExplanationColumn): string[] {
      return [
        ...columnInfoLines(column, this.tr, (value) => this.text(value)),
        this.schemaNote(column),
      ];
    },
    /** Under structured output the AI answers with the configured name, whatever the header on the document says. */
    schemaNote(column: TableExplanationColumn): string {
      return this.schemaUsed && column.basis === 'identity'
        ? this.$t('ai_explain_info_basis_schema')
        : '';
    },
    headClass(column: TableExplanationColumn): string {
      const state = this.columnState(column);
      if (state === 'missing') return 'bg-warning/10';
      if (state === 'filled') return 'bg-card';
      if (state === 'hidden') return 'bg-muted/40 italic text-muted-foreground';
      return 'bg-muted/40 text-muted-foreground';
    },
    originLabel(column: TableExplanationColumn): string {
      return originShort(column, this.tr);
    },
    /** The step's own explanation, plus the counts that do not fit on the card. */
    stepInfo(step: { key: string; infoKey: string }): string[] {
      const key = step.key;
      const steps = this.explanation?.steps;
      const lines = [this.$t(step.infoKey)];
      if (key === 'extraction') {
        const tagged = this.tableColumns
          .filter((c) => c.hint)
          .map((c) => c.label);
        lines.push(
          tagged.length
            ? this.$t('ai_explain_tag_columns', { columns: tagged.join(', ') })
            : this.$t('ai_explain_tag_none'),
        );
      }
      if (key === 'mapping') {
        for (const basis of ['identity', 'mapping', 'synonym']) {
          const names = this.tableColumns
            .filter((c) => c.basis === basis)
            .map((c) => c.label);
          if (names.length)
            lines.push(
              this.$t(`ai_explain_mapped_${basis}`, {
                columns: names.join(', '),
              }),
            );
        }
      }
      if (key === 'result' && steps?.result)
        lines.push(
          `${steps.result.non_ai_columns} ${this.$t('ai_explain_non_ai_columns')}`,
        );
      return lines;
    },
    dotClass(column: TableExplanationColumn): string {
      return STATE_DOT[this.columnState(column)];
    },
    pillClass(tone: string): string {
      if (tone === 'ok')
        return 'border-success/40 bg-success/10 text-foreground';
      if (tone === 'warn' || tone === 'off')
        return 'border-warning/50 bg-warning/10 text-foreground';
      if (tone === 'unverified')
        return 'border-primary/40 bg-primary/10 text-foreground';
      return 'border-border bg-muted text-muted-foreground';
    },
    severityIcon(severity: string): string {
      if (severity === 'high') return 'mdi:alert-circle-outline';
      if (severity === 'medium') return 'mdi:alert-outline';
      return 'mdi:information-outline';
    },
    severityColor(severity: string): string {
      if (severity === 'high') return 'var(--destructive)';
      if (severity === 'medium') return 'var(--warning)';
      return 'var(--muted-foreground)';
    },
    prettyRaw(column: TableExplanationColumn): string {
      return prettyRaw(column);
    },
    text(value: PipelineText | null | undefined): string {
      if (!value) return '';
      return (
        (this.locale === 'de' ? value.de : value.en) ||
        value.en ||
        value.de ||
        ''
      );
    },
    /**
     * The AI as the reader knows it: Fast / Full / Nexus plus who chose it —
     * never a vendor model id (DOCB-14569: "model bitte immer nur Fast, Full
     * oder Nexus").
     */
    tierText(explanation: TableExplanation): string {
      const tier =
        explanation.steps?.extraction?.tier ||
        explanation.run?.tier ||
        explanation.configuration?.model_selection?.tier ||
        this.$t('ai_explain_tier_unknown');
      const source = this.text(
        explanation.steps?.extraction?.tier_source_label ||
          explanation.configuration?.model_selection?.label,
      );
      return source ? `${tier} — ${source}` : String(tier);
    },
    /** The tier the API resolved for that call — never re-derived from a vendor id here. */
    callTier(call: TableExplanationCall): string {
      return call.tier || this.$t('ai_explain_tier_unknown');
    },
    checkText(valid: boolean | null | undefined): string {
      if (valid === true) return this.$t('ai_explain_check_passed');
      if (valid === false) return this.$t('ai_explain_check_failed');
      return this.$t('ai_explain_check_not_performed');
    },
    when(value: string | null | undefined): string {
      return value ? String(value).replace('T', ' ').slice(0, 19) : '—';
    },
  },
});
</script>

