/**
 * The analytics gate's closed door (DOCB-14569).
 *
 * The API keeps the table explanation behind `require_analytics_access` and
 * answers 403 with a stable `detail.code`. The UI opens a different door for
 * each: the module is off for the organisation (an admin can activate it
 * under Settings → Modules), or it is on and this user's role was not
 * granted the tab (an admin can grant it under Settings → Roles).
 */

/** Settings → Modules → Dashboards & Analytics: same path on dev and nova. */
export const MODULES_ROUTE = '/settings/modules/dashboards-analytics';

export type ForbiddenReason = 'module_off' | 'no_access';

/**
 * `analytics_module_off` → the module door; `analytics_access_denied` or any
 * other 403 → no access for this role. Anything else → null, so callers fall
 * through to the generic error.
 *
 * Two shapes reach here. A raw axios error keeps its status and a structured
 * `detail`. What the app really throws is different: doc2-api's
 * StarletteHTTPException handler sends `{success: false, message:
 * str(detail)}` — the code sits inside a Python repr — and
 * `ApiClient.handleError` throws that body without the status. So the code is
 * also read from `message`.
 */
export function forbiddenReason(error: unknown): ForbiddenReason | null {
  const e = error as {
    response?: { status?: number; data?: { detail?: { code?: string } } };
    status?: number;
    message?: unknown;
  } | null;
  const message = typeof e?.message === 'string' ? e.message : '';
  if (message.includes('analytics_module_off')) return 'module_off';
  if (message.includes('analytics_access_denied')) return 'no_access';
  const status = e?.response?.status ?? e?.status;
  if (status !== 403) return null;
  const code = e?.response?.data?.detail?.code;
  return code === 'analytics_module_off' ? 'module_off' : 'no_access';
}
