/**
 * Where an AI-table column got its values (CORE-6131), worded once for the
 * table header chip, the cell tooltip and the explanation dialog rows.
 */
import type { RouteLocationRaw } from 'vue-router';
import { FELLOWPRO_ICON_NAME } from 'src/icons/fellowpro-icon';
import type { TableExplanationColumn } from 'src/services/analytics/TableExplanationService';

export type ColumnState = 'filled' | 'missing' | 'off' | 'hidden';
type Translate = (key: string, params?: Record<string, unknown>) => string;

const BASIS_INFO_KEYS: Record<string, string> = {
  identity: 'ai_explain_info_basis_identity',
  mapping: 'ai_explain_info_basis_mapping',
  synonym: 'ai_explain_info_basis_synonym',
};

const BASIS_SHORT_KEYS: Record<string, string> = {
  identity: 'ai_explain_origin_identity',
  mapping: 'ai_explain_origin_mapping',
  synonym: 'ai_explain_origin_synonym',
};

export const STATE_DOT: Record<ColumnState, string> = {
  filled: 'bg-success',
  missing: 'bg-warning',
  off: 'bg-muted-foreground',
  hidden: 'border border-dashed border-muted-foreground',
};

export function columnState(column: TableExplanationColumn): ColumnState {
  if (column.hidden || column.hidden_by) return 'hidden';
  if ((column.state === 'filled' || column.state === 'partial') && column.basis)
    return 'filled';
  if (column.requested_from_ai) return 'missing';
  return 'off';
}

/** A source other than the AI, as the API names it (ocr, rule, …). */
function otherSource(column: TableExplanationColumn): string {
  const origin = String(column.origin || '');
  return origin && origin.toLowerCase() !== 'ai' ? origin : '';
}

export function prettyRaw(column: TableExplanationColumn): string {
  const key =
    String(column.raw_key || column.raw_name || '')
      .split('.')
      .pop() || '';
  return key.replace(/_/g, ' ').replace(/\b\w/g, (ch) => ch.toUpperCase());
}

/** The few words on the column header: "AI · 1:1", "not found", "AI off", … */
export function originShort(
  column: TableExplanationColumn,
  t: Translate,
): string {
  const state = columnState(column);
  if (state === 'filled') {
    const key = BASIS_SHORT_KEYS[String(column.basis || '')];
    return t(key || 'ai_explain_origin_ai');
  }
  const source = otherSource(column);
  if (source) return t('ai_explain_origin_source', { source });
  if (state === 'missing') return t('ai_explain_not_found');
  if (state === 'hidden') return t('ai_explain_hidden');
  // never told either way is not "switched off" — it was simply not set up
  if (column.use_ai === false) return t('ai_explain_ai_off');
  return t('ai_explain_not_configured');
}

/** The header icon for a column's origin, styled like the field source badge (CORE-6192). */
export function originIcon(column: TableExplanationColumn): { icon: string; color: string } {
  const state = columnState(column);
  if (state === 'filled') return { icon: FELLOWPRO_ICON_NAME, color: 'var(--vector-badge-text)' };
  if (otherSource(column)) return { icon: 'mdi:file-document-outline', color: 'var(--info-badge-text)' };
  if (state === 'missing') return { icon: 'mdi:alert-circle-outline', color: 'var(--warning-badge-text)' };
  if (state === 'hidden') return { icon: 'mdi:eye-off-outline', color: 'var(--muted-foreground)' };
  return { icon: 'mdi:robot', color: 'var(--muted-foreground)' };
}

export function basisLine(
  column: TableExplanationColumn,
  t: Translate,
  text: (v: TableExplanationColumn['how']) => string,
): string {
  const key = BASIS_INFO_KEYS[String(column.basis || '')];
  return key ? t(key, { column: column.label }) : text(column.how);
}

export function rawInfoLines(
  column: TableExplanationColumn,
  t: Translate,
  text: (v: TableExplanationColumn['how']) => string,
): string[] {
  return [
    t('ai_explain_info_raw', { raw: prettyRaw(column) }),
    column.example
      ? t('ai_explain_info_example', { value: column.example })
      : '',
    basisLine(column, t, text),
    column.collision ? t('ai_explain_info_collision') : '',
  ].filter(Boolean);
}

/** Everything known about one configured column, one sentence per line. */
export function columnInfoLines(
  column: TableExplanationColumn,
  t: Translate,
  text: (v: TableExplanationColumn['how']) => string,
): string[] {
  const state = columnState(column);
  const lines: string[] = [];
  if (state === 'filled') {
    lines.push(
      t('ai_explain_info_filled', {
        filled: column.filled_rows,
        rows: column.row_count,
      }),
      column.raw_key
        ? t('ai_explain_info_raw', { raw: prettyRaw(column) })
        : '',
      basisLine(column, t, text),
    );
  } else if (otherSource(column)) {
    lines.push(t('ai_explain_origin_source', { source: otherSource(column) }));
  } else if (state === 'missing') {
    lines.push(t('ai_explain_info_missing'));
  } else if (state === 'hidden') {
    lines.push(t('ai_explain_info_hidden'));
  } else if (column.use_ai === false) {
    lines.push(t('ai_explain_info_ai_off'));
  } else {
    lines.push(t('ai_explain_info_not_configured'));
  }
  if (column.discarded_reason)
    lines.push(
      t('ai_explain_info_discarded', { reason: column.discarded_reason }),
    );
  if (column.hint)
    lines.push(t('ai_explain_info_ai_hint', { hint: column.hint }));
  if (column.required) lines.push(t('ai_explain_info_required'));
  lines.push(t('ai_explain_info_key', { key: column.key }));
  return lines.filter(Boolean);
}

/** The explanation page in its own browser window, next to the validation screen. */
export function openExplanationWindow(
  router: { resolve: (to: RouteLocationRaw) => { href: string } },
  docId: string,
  tableName: string | null,
): void {
  const { href } = router.resolve({
    name: 'table-explanation',
    params: { id: docId },
    query: tableName ? { table: tableName } : {},
  });
  window.open(href, '_blank', 'noopener');
}
