<!--
  The two reads that used to sit inside the table explanation (CORE-6131),
  each behind its own button: the processing chain the document went through,
  and the KI-Advisor (Nexus). Loaded on open, never before — the advice takes
  8–15 s and is only worth that when someone asks for it.
-->
<template>
  <q-dialog :model-value="modelValue" @update:model-value="close">
    <q-card
      class="insight-dialog overflow-hidden bg-card text-sm text-foreground"
      :data-test="`ai-insight-${kind}`"
    >
      <q-toolbar class="shrink-0 text-white secondary-toolbar">
        <q-toolbar-title class="min-w-0">
          <h2 class="m-0 truncate text-base font-semibold leading-tight">
            {{
              $t(
                kind === 'pipeline'
                  ? 'ai_explain_pipeline'
                  : 'ai_explain_advice_title',
              )
            }}
          </h2>
        </q-toolbar-title>
        <q-btn
          flat
          round
          icon="close"
          class="text-white"
          :aria-label="$t('close')"
          data-test="ai-insight-close"
          @click="close(false)"
        />
      </q-toolbar>

      <div class="insight-dialog__body min-h-0 flex-1 overflow-auto">
        <div
          v-if="loading"
          class="flex flex-col items-center gap-2 py-10 text-muted-foreground"
          data-test="ai-insight-loading"
        >
          <q-spinner size="32px" />
          <span class="text-xs">{{
            $t(
              kind === 'pipeline'
                ? 'ai_explain_loading'
                : 'ai_explain_advice_loading',
            )
          }}</span>
        </div>

        <div
          v-else-if="forbidden"
          class="flex flex-col items-start gap-2"
          :data-test="`ai-insight-forbidden-${forbidden}`"
        >
          <Icon icon="mdi:lock-outline" color="var(--warning)" class="size-7" />
          <p class="m-0 text-base font-semibold">
            {{
              forbidden === 'module_off'
                ? $t('ai_explain_license_title')
                : $t('ai_explain_user_access_title')
            }}
          </p>
          <p class="m-0 text-muted-foreground">
            {{
              forbidden === 'module_off'
                ? $t('ai_explain_license_required')
                : $t('ai_explain_user_access_required')
            }}
          </p>
        </div>

        <div
          v-else-if="error"
          role="alert"
          class="rounded-md border border-destructive/40 bg-destructive/5 px-3 py-2 text-destructive"
          data-test="ai-insight-error"
        >
          {{
            $t(
              kind === 'pipeline'
                ? 'ai_explain_pipeline_failed'
                : 'ai_explain_advice_failed',
            )
          }}
        </div>

        <template v-else-if="kind === 'pipeline'">
          <ol
            v-if="stages.length"
            class="m-0 list-none p-0"
            data-test="ai-insight-steps"
          >
            <li
              v-for="(stage, index) in stages"
              :key="stage.key"
              class="insight-step"
              :data-state="stage.state || 'unknown'"
              :data-test="`ai-insight-step-${stage.key}`"
            >
              <div class="insight-step__rail">
                <span
                  class="insight-step__no"
                  :class="`insight-step__no--${tone(stage)}`"
                  >{{ stage.no ?? index + 1 }}</span
                >
                <span
                  v-if="index < stages.length - 1"
                  class="insight-step__line"
                  aria-hidden="true"
                />
              </div>
              <div
                class="insight-step__body"
                :class="{ 'insight-step__body--stop': stage.is_first_blocker }"
              >
                <div class="insight-line">
                  <span class="insight-step__title">{{
                    text(stage.label)
                  }}</span>
                  <span
                    class="insight-pill"
                    :class="`insight-pill--${tone(stage)}`"
                    >{{ stateText(stage) }}</span
                  >
                  <span
                    v-if="stage.is_first_blocker"
                    class="insight-pill insight-pill--bad"
                    data-test="ai-insight-stopped-here"
                    >{{ $t('pipeline_flow_stopped_here') }}</span
                  >
                  <ExplanationInfo :lines="stageInfo(stage)" />
                </div>
                <div v-if="reasonText(stage)" class="insight-step__reason">
                  {{ reasonText(stage) }}
                </div>
              </div>
            </li>
          </ol>
          <p
            v-else
            class="m-0 rounded-md border border-border bg-muted px-3 py-2 text-muted-foreground"
            data-test="ai-insight-empty"
          >
            {{ $t('ai_explain_pipeline_empty') }}
          </p>
        </template>

        <template v-else>
          <p
            v-if="advice && text(advice.summary)"
            class="m-0 mb-3 leading-relaxed"
          >
            {{ text(advice.summary) }}
          </p>
          <ul
            v-if="advice?.improvements?.length"
            class="m-0 flex list-none flex-col gap-2 p-0"
          >
            <li
              v-for="(item, index) in advice.improvements"
              :key="`${item.action}-${item.target || index}`"
              class="flex gap-3 rounded-md border border-primary/30 bg-primary/5 px-3 py-2"
              :data-test="`ai-insight-advice-${item.action}`"
            >
              <Icon
                icon="mdi:lightbulb-outline"
                color="var(--primary)"
                class="mt-0.5 size-4 shrink-0"
              />
              <div class="flex min-w-0 flex-col gap-0.5">
                <b class="font-semibold"
                  >{{ text(item.action_label) || item.action
                  }}<template v-if="item.target_label || item.target">
                    → {{ text(item.target_label) || item.target }}</template
                  ></b
                >
                <span>{{ text(item.why) }}</span>
                <span class="text-muted-foreground">{{ text(item.how) }}</span>
              </div>
            </li>
          </ul>
          <p
            v-else
            class="m-0 rounded-md border border-border bg-muted px-3 py-2 text-muted-foreground"
            data-test="ai-insight-empty"
          >
            {{ $t('ai_explain_advice_empty') }}
          </p>
        </template>
      </div>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { computed, defineComponent, inject, type PropType } from 'vue';
import { useTolgee } from '@tolgee/vue';
import { Icon } from '@iconify/vue';
import ExplanationInfo from 'src/components/document/ExplanationInfo.vue';
import {
  pipelineExplanationService,
  tableExplanationService,
} from 'src/services';
import type {
  PipelineStage,
  PipelineText,
} from 'src/services/analytics/PipelineExplanationService';
import type { TableExplanationAdvice } from 'src/services/analytics/TableExplanationService';
import {
  forbiddenReason,
  type ForbiddenReason,
} from 'src/components/document/tableExplanationAccess';

export default defineComponent({
  name: 'AITableInsightDialog',
  components: { ExplanationInfo, Icon },
  props: {
    modelValue: { type: Boolean, required: true },
    kind: { type: String as PropType<'pipeline' | 'advice'>, required: true },
    docId: { type: String, required: true },
    tableName: { type: String as PropType<string | null>, default: null },
  },
  emits: ['update:modelValue'],
  setup() {
    const tolgee = inject('tolgeeContext', null)
      ? useTolgee(['language'])
      : null;
    const uiLanguage = computed(() => tolgee?.value?.getLanguage() || '');
    return { uiLanguage };
  },
  data() {
    return {
      loading: false,
      error: false,
      forbidden: '' as ForbiddenReason | '',
      stages: [] as PipelineStage[],
      advice: null as TableExplanationAdvice | null,
      // a late answer from an earlier open must not overwrite the current one
      requestGeneration: 0,
    };
  },
  computed: {
    locale(): string {
      const raw = String(this.uiLanguage || this.$i18n?.locale || 'en');
      return raw.split('-')[0] || 'en';
    },
  },
  watch: {
    modelValue: {
      handler(open: boolean) {
        if (open) void this.load();
      },
      immediate: true,
    },
  },
  methods: {
    async load() {
      const generation = ++this.requestGeneration;
      this.loading = true;
      this.error = false;
      this.forbidden = '';
      this.stages = [];
      this.advice = null;
      try {
        if (this.kind === 'pipeline') {
          const pipeline = await pipelineExplanationService.getDocumentPipeline(
            this.docId,
          );
          if (generation !== this.requestGeneration) return;
          this.stages = pipeline?.stages || [];
        } else {
          const withAdvice =
            await tableExplanationService.getDocumentTableExplanation(
              this.docId,
              this.tableName,
              { includeRecommendation: true },
            );
          if (generation !== this.requestGeneration) return;
          this.advice = withAdvice?.advice || null;
        }
      } catch (error) {
        if (generation !== this.requestGeneration) return;
        const reason = forbiddenReason(error);
        if (reason) this.forbidden = reason;
        else this.error = true;
      } finally {
        if (generation === this.requestGeneration) this.loading = false;
      }
    },
    close(value: boolean) {
      this.$emit('update:modelValue', value === true);
    },
    tone(stage: PipelineStage): 'ok' | 'bad' | 'muted' | 'unknown' {
      const state = String(stage.state || 'unknown');
      if (state === 'passed') return 'ok';
      if (state === 'blocked' || state === 'failed') return 'bad';
      if (state === 'unknown') return 'unknown';
      return 'muted';
    },
    stateText(stage: PipelineStage): string {
      return this.text(stage.state_label) || String(stage.state || '');
    },
    /** Why a stage stopped the document; nothing for the ones that did not. */
    reasonText(stage: PipelineStage): string {
      if (!stage.reason_code) return '';
      if (stage.state !== 'blocked' && stage.state !== 'failed') return '';
      const key = `touchless_reason_${stage.reason_code.toLowerCase()}`;
      const translated = this.$t(key);
      return translated === key ? stage.reason_code : translated;
    },
    stageInfo(stage: PipelineStage): string[] {
      return [this.text(stage.summary), this.text(stage.analysis?.analysis)];
    },
    text(value: PipelineText | null | undefined): string {
      if (!value) return '';
      return (
        (this.locale === 'de' ? value.de : value.en) ||
        value.en ||
        value.de ||
        ''
      );
    },
  },
});
</script>

